<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import {useRoute} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {blankRule,chooseCompany,copy} from '../payrollUi'
import type {PayrollHomeData,SalaryTemplate} from '../payrollTypes'
import PayRuleSummary from '../components/PayRuleSummary.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),editing=!!route.params.id,id=String(route.params.id||crypto.randomUUID()),{api,r,t,english,base,loading,failure,notice,load}=usePayrollPage(),company=ref(''),found=ref(false),managed=ref(false),draft=reactive({expectedVersion:0,name:'',enabled:true,rule:blankRule()})
onMounted(()=>void load(async()=>{const h=await api().get<PayrollHomeData>('/payroll-home'),c=chooseCompany(h,String(route.query.companyId||''));return {c,list:editing?await api().get<SalaryTemplate[]>('/salary-templates?companyId='+c):[]}},v=>{company.value=v.c;if(editing){const s=v.list.find(x=>x.id===id);if(!s){failure.value=t('notFound');return}managed.value=!!s.governanceSource;Object.assign(draft,{expectedVersion:s.version,name:s.name,enabled:s.enabled,rule:copy(s.rule)})}found.value=true}))
</script>
<template><section class="wf-panel"><h2>{{english()?(editing?'View salary template':'Prepare a salary template'):(editing?'查看工资模板':'准备工资模板')}}</h2><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><div v-if="found&&!loading"><p v-if="editing&&!managed" class="wf-hint">{{english()?'Legacy shared template: read-only. Create and publish a master, or request a store derivation from the template library.':'旧共享模板仅保留历史选用与查看。请到门店模板库创建并发布母版，或从已有采用发起本店派生申请。'}}</p><p v-if="!editing" class="wf-hint">{{english()?'Create and publish payroll templates from the template library.':'请从门店模板库创建并发布工资母版，再显式采用。'}}</p><RouterLink class="wf-button" :to="{path:base+'/pay-template-library',query:{companyId:company}}">{{english()?'Store template library / publication':'门店模板库／发布母版'}}</RouterLink><p v-if="managed" class="wf-hint">{{english()?'Published store template: fixed and read-only. Manage versions in the store template library.':'已发布门店模板为固定只读快照，请在门店模板库管理采用版本。'}}</p><fieldset v-if="editing" :disabled="true"><label>{{r('name')}}<input v-model="draft.name" required maxlength="100"></label><PayRuleSummary :rule="draft.rule"/><label class="wf-check"><input v-model="draft.enabled" type="checkbox">{{r('enabled')}}</label></fieldset><p class="wf-hint">{{r('templateHint')}} {{r('supportHint')}}</p><footer class="wf-form-actions"><RouterLink class="wf-button" :to="{path:base+'/salary-templates',query:{companyId:company}}">{{english()?'Back to template list':'返回模板列表'}}</RouterLink></footer></div></section></template>
